60	// LatestTunnelConnection returns latest tunnel connection from the list
61	// of tunnel connections, if no connections found, returns NotFound error
62	func LatestTunnelConnection(conns []TunnelConnection) (TunnelConnection, error) {
63		var lastConn TunnelConnection
64		for i := range conns {
65			conn := conns[i]
66			if lastConn == nil || conn.GetLastHeartbeat().After(lastConn.GetLastHeartbeat()) {
67				lastConn = conn
68			}
69		}
70		if lastConn == nil {
71			return nil, trace.NotFound("no connections found")
72		}
73		return lastConn, nil
74	}
