78	func TunnelConnectionStatus(clock clockwork.Clock, conn TunnelConnection, offlineThreshold time.Duration) string {
79		diff := clock.Now().Sub(conn.GetLastHeartbeat())
80		if diff < offlineThreshold {
81			return teleport.RemoteClusterStatusOnline
82		}
83		return teleport.RemoteClusterStatusOffline
