357	func (a *AuthServer) updateRemoteClusterStatus(remoteCluster services.RemoteCluster) error {
358		clusterConfig, err := a.GetClusterConfig()
359		if err != nil {
360			return trace.Wrap(err)
361		}
362		keepAliveCountMax := clusterConfig.GetKeepAliveCountMax()
363		keepAliveInterval := clusterConfig.GetKeepAliveInterval()
364	
365		// fetch tunnel connections for the cluster to update runtime status
366		connections, err := a.GetTunnelConnections(remoteCluster.GetName())
367		if err != nil {
368			return trace.Wrap(err)
369		}
370		remoteCluster.SetConnectionStatus(teleport.RemoteClusterStatusOffline)
371		lastConn, err := services.LatestTunnelConnection(connections)
372		if err == nil {
373			offlineThreshold := time.Duration(keepAliveCountMax) * keepAliveInterval
374			tunnelStatus := services.TunnelConnectionStatus(a.clock, lastConn, offlineThreshold)
375			remoteCluster.SetConnectionStatus(tunnelStatus)
376			remoteCluster.SetLastHeartbeat(lastConn.GetLastHeartbeat())
377		}
378		return nil
379	}
